<script setup>
import {computed,onMounted,ref} from 'vue';
import {router,usePage} from '@inertiajs/vue3';
import PortalLayout from '../../../Layouts/PortalLayout.vue';
const props=defineProps({payment:Object});const page=usePage();const hi=computed(()=>page.props.locale==='hi');const loading=ref(false);const error=ref('');
onMounted(()=>{if(!window.Razorpay){const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.async=true;document.head.appendChild(script);}});
function pay(){error.value='';if(!window.Razorpay){error.value=hi.value?'भुगतान विंडो लोड नहीं हुई। पुनः प्रयास करें।':'Payment checkout did not load. Please retry.';return;}loading.value=true;
const options={key:props.payment.key_id,amount:props.payment.amount,currency:props.payment.currency,name:'ExamTestHub',description:props.payment.series_title,order_id:props.payment.order_id,prefill:{name:props.payment.student_name,email:props.payment.student_email},theme:{color:'#4f46e5'},handler(response){router.post('/student/payments/'+props.payment.id+'/verify',response,{onFinish:()=>{loading.value=false;},onError:()=>{error.value=hi.value?'भुगतान सत्यापन विफल हुआ। सहायता से संपर्क करें।':'Payment verification failed. Please contact support.';}});},modal:{ondismiss(){loading.value=false;}}};
const checkout=new window.Razorpay(options);checkout.on('payment.failed',response=>{loading.value=false;error.value=response.error?.description||'Payment failed. You can retry from the test series page.';});checkout.open();}
</script>
<template><PortalLayout portal="student" :title="hi?'भुगतान पूरा करें':'Complete payment'" :subtitle="payment.series_title"><section class="max-w-xl rounded-2xl border bg-white p-6"><p class="text-sm text-slate-500">{{hi?'देय राशि':'Amount payable'}}</p><p class="mt-1 text-3xl font-extrabold">{{payment.currency}} {{(payment.amount/100).toFixed(2)}}</p><p class="mt-3 text-sm text-slate-600">{{hi?'भुगतान Razorpay के सुरक्षित चेकआउट पर प्रोसेस होगा।':'Your payment will be processed through Razorpay Checkout.'}}</p><p v-if="error" class="mt-4 rounded-lg bg-red-50 p-3 text-sm text-red-700">{{error}}</p><button @click="pay" :disabled="loading" class="mt-6 rounded-xl bg-indigo-600 px-5 py-3 font-bold text-white disabled:opacity-50">{{loading?(hi?'प्रोसेस हो रहा है…':'Processing…'):(hi?'Razorpay से भुगतान करें':'Pay securely with Razorpay')}}</button></section></PortalLayout></template>
